import { randomUUID } from "node:crypto";

import { context } from "@opentelemetry/api";
import type { IAppResponse, StreamConfig } from "shared";

import { AppKitError } from "../errors/base";
import { ExecutionError } from "../errors/execution";
import { createLogger } from "../logging/logger";
import { EventRingBuffer } from "./buffers";
import { streamDefaults } from "./defaults";
import { SSEWriter } from "./sse-writer";
import { StreamRegistry } from "./stream-registry";
import { clearGraceTimer, clearRemovalTimer } from "./timers";
import { SSEErrorCode, type StreamEntry, type StreamOperation } from "./types";
import { StreamValidator } from "./validator";

const logger = createLogger("stream");

// main entry point for Server-Sent events streaming
export class StreamManager {
  private activeOperations: Set<StreamOperation>;
  private streamRegistry: StreamRegistry;
  private sseWriter: SSEWriter;
  private maxEventSize: number;
  private bufferTTL: number;
  private disconnectGraceMs: number;

  constructor(options?: StreamConfig) {
    this.streamRegistry = new StreamRegistry(
      options?.maxActiveStreams ?? streamDefaults.maxActiveStreams,
    );
    this.sseWriter = new SSEWriter();
    this.maxEventSize = options?.maxEventSize ?? streamDefaults.maxEventSize;
    this.bufferTTL = options?.bufferTTL ?? streamDefaults.bufferTTL;
    this.disconnectGraceMs =
      options?.disconnectGraceMs ?? streamDefaults.disconnectGraceMs;
    this.activeOperations = new Set();
  }

  // main streaming method - handles new connection and reconnection
  async stream(
    res: IAppResponse,
    handler: (signal: AbortSignal) => AsyncGenerator<any, void, unknown>,
    options?: StreamConfig,
    ownerKey?: string,
  ): Promise<void> {
    const { streamId } = options || {};

    // check if response is already closed
    if (res.writableEnded || res.destroyed) {
      return;
    }

    // setup SSE headers
    this.sseWriter.setupHeaders(res);

    // handle reconnection
    if (streamId && StreamValidator.validateStreamId(streamId)) {
      const existingStream = this.streamRegistry.get(streamId);
      if (existingStream) {
        // Enforce per-user binding: the stream's owner key must match the
        // requesting caller's owner key. This prevents cross-user stream
        // takeover via guessed/leaked stream IDs (the SSE registry was
        // previously a global lookup with no authorization step).
        if (existingStream.ownerKey !== ownerKey) {
          this.sseWriter.writeError(
            res,
            randomUUID(),
            "Stream not found or access denied",
            SSEErrorCode.STREAM_FORBIDDEN,
          );
          res.end();
          return;
        }
        return this._attachToExistingStream(res, existingStream, options);
      }
    }

    // if stream does not exist, create a new one
    return this._createNewStream(res, handler, options, ownerKey);
  }

  // abort all active operations
  abortAll(): void {
    // pending disconnect-grace timers are cleared by streamRegistry.clear() below
    this.activeOperations.forEach((operation) => {
      if (operation.heartbeat) clearInterval(operation.heartbeat);
      operation.controller.abort(
        new DOMException("Server shutdown", "AbortError"),
      );
    });
    this.activeOperations.clear();
    this.streamRegistry.clear();
  }

  // get the number of active operations
  getActiveCount(): number {
    return this.activeOperations.size;
  }

  // attach to existing stream
  private async _attachToExistingStream(
    res: IAppResponse,
    streamEntry: StreamEntry,
    options?: StreamConfig,
  ): Promise<void> {
    // handle reconnection - replay missed events
    const lastEventId = res.req?.headers["last-event-id"];

    if (StreamValidator.validateEventId(lastEventId)) {
      // cast to string after validation
      const validEventId = lastEventId as string;
      if (streamEntry.eventBuffer.has(validEventId)) {
        const missedEvents =
          streamEntry.eventBuffer.getEventsSince(validEventId);
        // broadcast missed events to client
        for (const event of missedEvents) {
          if (options?.userSignal?.aborted) break;
          this.sseWriter.writeBufferedEvent(res, event);
        }
      } else {
        // buffer overflow - send warning
        this.sseWriter.writeBufferOverflowWarning(res, validEventId);
      }
    }

    // a reconnecting client cancels the pending disconnect-grace abort
    clearGraceTimer(streamEntry);

    // a reconnect cancels any pending registry removal so the entry isn't
    // pulled out from under the newly attached client
    clearRemovalTimer(streamEntry);

    // add client to stream entry
    streamEntry.clients.add(res);
    streamEntry.lastAccess = Date.now();

    // start heartbeat
    const combinedSignal = this._combineSignals(
      streamEntry.abortController.signal,
      options?.userSignal,
    );
    const heartbeat = this.sseWriter.startHeartbeat(res, combinedSignal);

    // track operation
    const streamOperation: StreamOperation = {
      controller: streamEntry.abortController,
      type: "stream",
      heartbeat,
    };
    this.activeOperations.add(streamOperation);

    // handle client disconnect
    res.on("close", () => {
      clearInterval(heartbeat);
      streamEntry.clients.delete(res);
      this.activeOperations.delete(streamOperation);

      // grace-abort instead of aborting now, so a reconnect can resume
      if (streamEntry.clients.size === 0 && !streamEntry.isCompleted) {
        this._scheduleGraceAbort(streamEntry);
      }

      // cleanup if stream is completed and no clients are connected
      this._scheduleRemovalAfterTTL(streamEntry);
    });

    // if stream is completed, close connection
    if (streamEntry.isCompleted) {
      res.end();
      // cleanup operation
      this.activeOperations.delete(streamOperation);
      clearInterval(heartbeat);
      // we deliberately ended this client, so drop it from the entry and
      // schedule removal now instead of relying on the transport's `close`
      // event (the close handler's later delete is a safe no-op)
      streamEntry.clients.delete(res);
      this._scheduleRemovalAfterTTL(streamEntry);
    }
  }
  private async _createNewStream(
    res: IAppResponse,
    handler: (signal: AbortSignal) => AsyncGenerator<any, void, unknown>,
    options?: StreamConfig,
    ownerKey?: string,
  ): Promise<void> {
    const streamId = options?.streamId ?? randomUUID();

    // abort stream if response is closed
    if (res.writableEnded || res.destroyed) {
      return;
    }

    const abortController = new AbortController();

    // create event buffer
    const eventBuffer = new EventRingBuffer(
      options?.bufferSize ?? streamDefaults.bufferSize,
    );

    // setup signals and heartbeat
    const combinedSignal = this._combineSignals(
      abortController.signal,
      options?.userSignal,
    );
    const heartbeat = this.sseWriter.startHeartbeat(res, combinedSignal);

    // capture the current trace context at stream creation time
    const traceContext = context.active();

    // abort stream if response is closed
    if (res.writableEnded || res.destroyed) {
      clearInterval(heartbeat);
      return;
    }

    // create stream entry
    const streamEntry: StreamEntry = {
      streamId,
      ownerKey,
      generator: handler(combinedSignal),
      eventBuffer,
      clients: new Set([res]),
      isCompleted: false,
      lastAccess: Date.now(),
      abortController,
      traceContext,
    };
    this.streamRegistry.add(streamEntry);

    // track operation
    const streamOperation: StreamOperation = {
      controller: abortController,
      type: "stream",
      heartbeat,
    };
    this.activeOperations.add(streamOperation);

    res.on("close", () => {
      clearInterval(heartbeat);
      this.activeOperations.delete(streamOperation);
      streamEntry.clients.delete(res);

      // grace-abort instead of aborting now, so a reconnect can resume
      if (streamEntry.clients.size === 0 && !streamEntry.isCompleted) {
        this._scheduleGraceAbort(streamEntry);
      }

      // if the stream already finished (completed or errored), schedule
      // registry removal once the buffer TTL elapses so completed streams
      // don't accumulate in the registry forever
      this._scheduleRemovalAfterTTL(streamEntry);
    });

    await this._processGeneratorInBackground(streamEntry);

    // cleanup
    clearInterval(heartbeat);
    this.activeOperations.delete(streamOperation);
  }

  private async _processGeneratorInBackground(
    streamEntry: StreamEntry,
  ): Promise<void> {
    // run the entire generator processing within the captured trace context
    return context.with(streamEntry.traceContext, async () => {
      try {
        // retrieve all events from generator
        for await (const event of streamEntry.generator) {
          if (streamEntry.abortController.signal.aborted) break;
          const eventId = randomUUID();
          const eventData = JSON.stringify(event);

          // validate event size
          if (eventData.length > this.maxEventSize) {
            const errorMsg = `Event exceeds max size of ${this.maxEventSize} bytes`;
            const errorCode = SSEErrorCode.INVALID_REQUEST;
            // broadcast error to all connected clients
            this._broadcastErrorToClients(
              streamEntry,
              eventId,
              errorMsg,
              errorCode,
            );
            continue;
          }

          // buffer event for reconnection
          streamEntry.eventBuffer.add({
            id: eventId,
            type: event.type,
            data: eventData,
            timestamp: Date.now(),
          });

          // broadcast to all connected clients
          this._broadcastEventsToClients(streamEntry, eventId, event);
          streamEntry.lastAccess = Date.now();
        }

        this._finalizeStream(streamEntry);
      } catch (error) {
        // Two distinct messages: a *raw* one for server-side logs (full
        // detail, statement fragments, correlation IDs) and a *client*
        // one for the SSE payload (sanitized, stable, safe to render in
        // a UI). Mixing them leaks upstream wording to anyone connected
        // to the stream — see CWE-209.
        const rawMsg =
          error instanceof Error ? error.message : "Internal server error";
        const clientMsg =
          error instanceof AppKitError
            ? error.clientMessage
            : "Internal server error";
        // Upstream structured code (e.g. RESULT_TOO_LARGE_FOR_JSON_FALLBACK,
        // NOT_IMPLEMENTED). UI should branch on this, not on `error`.
        const upstreamCode =
          error instanceof ExecutionError ? error.errorCode : undefined;
        const errorEventId = randomUUID();
        const errorCode = this._categorizeError(error);

        // client cancellation is a normal control-flow signal, not a failure
        if (errorCode === SSEErrorCode.STREAM_ABORTED) {
          logger.info("Stream aborted by client (code=%s)", errorCode);
          this._finalizeStream(streamEntry);
          return;
        }

        logger.error(
          "Stream execution failed: %s (code=%s upstreamCode=%s)",
          rawMsg,
          errorCode,
          upstreamCode ?? "n/a",
        );

        const payload: Record<string, unknown> = {
          error: clientMsg,
          code: errorCode,
        };
        if (upstreamCode) payload.errorCode = upstreamCode;

        // buffer error event
        streamEntry.eventBuffer.add({
          id: errorEventId,
          type: "error",
          data: JSON.stringify(payload),
          timestamp: Date.now(),
        });

        // send error event to all connected clients
        this._broadcastErrorToClients(
          streamEntry,
          errorEventId,
          clientMsg,
          errorCode,
          true,
          upstreamCode,
        );
        // the broadcast above already ended the connected clients; finalize
        // still detaches them so removal is scheduled without waiting on a
        // transport `close` event
        this._finalizeStream(streamEntry);
      }
    });
  }

  private _combineSignals(
    internalSignal?: AbortSignal,
    userSignal?: AbortSignal,
  ): AbortSignal {
    if (!userSignal) return internalSignal || new AbortController().signal;

    const signals = [internalSignal, userSignal].filter(
      Boolean,
    ) as AbortSignal[];
    const controller = new AbortController();

    signals.forEach((signal) => {
      if (signal?.aborted) {
        controller.abort(signal.reason);
        return;
      }

      signal?.addEventListener(
        "abort",
        () => {
          controller.abort(signal.reason);
        },
        { once: true },
      );
    });
    return controller.signal;
  }

  // broadcast events to all connected clients
  private _broadcastEventsToClients(
    streamEntry: StreamEntry,
    eventId: string,
    event: any,
  ): void {
    for (const client of streamEntry.clients) {
      if (!client.writableEnded) {
        this.sseWriter.writeEvent(client, eventId, event);
      }
    }
  }

  // broadcast error to all connected clients
  private _broadcastErrorToClients(
    streamEntry: StreamEntry,
    eventId: string,
    errorMessage: string,
    errorCode: SSEErrorCode,
    closeClients: boolean = false,
    upstreamCode?: string,
  ): void {
    for (const client of streamEntry.clients) {
      if (!client.writableEnded) {
        this.sseWriter.writeError(
          client,
          eventId,
          errorMessage,
          errorCode,
          upstreamCode,
        );
        if (closeClients) {
          client.end();
        }
      }
    }
  }

  private _finalizeStream(streamEntry: StreamEntry): void {
    streamEntry.isCompleted = true;
    clearGraceTimer(streamEntry);
    this._closeAllClients(streamEntry);
    this._scheduleRemovalAfterTTL(streamEntry);
  }

  // close all connected clients and remove them from the stream entry.
  // We are deliberately terminating these connections, so cleanup must not
  // depend on the transport emitting a `close` event for each client (it may
  // never fire). The close handlers' later `clients.delete(...)` calls remain
  // safe no-ops.
  private _closeAllClients(streamEntry: StreamEntry): void {
    for (const client of streamEntry.clients) {
      if (!client.writableEnded) {
        client.end();
      }
    }
    streamEntry.clients.clear();
  }

  // abort the generator after the grace window unless a client reconnects first
  private _scheduleGraceAbort(streamEntry: StreamEntry): void {
    // clear any existing timer to avoid stacking
    clearGraceTimer(streamEntry);

    const timer = setTimeout(() => {
      streamEntry.disconnectGraceTimer = undefined;
      if (streamEntry.clients.size === 0 && !streamEntry.isCompleted) {
        streamEntry.abortController.abort(
          new DOMException("Client disconnected (grace expired)", "AbortError"),
        );
      }
    }, this.disconnectGraceMs);

    // never keep the process alive solely for a grace timer
    timer.unref?.();
    streamEntry.disconnectGraceTimer = timer;
  }

  // schedule registry removal once a finished (completed or errored) stream
  // has no connected clients. The event buffer stays available for
  // reconnect replay for `bufferTTL` after the last client disconnects;
  // after that the stream entry is removed from the registry so it can be
  // garbage collected.
  private _scheduleRemovalAfterTTL(streamEntry: StreamEntry): void {
    if (!streamEntry.isCompleted || streamEntry.clients.size > 0) {
      return;
    }

    // at most one removal timer per stream: rescheduling replaces any
    // pending timer instead of stacking a new one (each pending timer pins
    // the entry's buffer/generator/trace context for the full TTL)
    clearRemovalTimer(streamEntry);

    // mark the moment the stream became idle so a reconnect during the TTL
    // window (which refreshes lastAccess) makes the pending timer a no-op
    streamEntry.lastAccess = Date.now();

    streamEntry.removalTimer = setTimeout(() => {
      streamEntry.removalTimer = undefined;
      // safety net: no-op if a client reconnected during the TTL window;
      // a fresh removal is scheduled when that client disconnects
      if (
        streamEntry.clients.size === 0 &&
        Date.now() - streamEntry.lastAccess >= this.bufferTTL
      ) {
        this.streamRegistry.remove(streamEntry.streamId);
      }
    }, this.bufferTTL);

    // don't keep the process alive just to clean up finished streams
    streamEntry.removalTimer.unref?.();
  }

  private _categorizeError(error: unknown): SSEErrorCode {
    if (error instanceof Error) {
      const message = error.message.toLowerCase();
      if (message.includes("timeout") || message.includes("timed out")) {
        return SSEErrorCode.TIMEOUT;
      }

      if (message.includes("unavailable") || message.includes("econnrefused")) {
        return SSEErrorCode.TEMPORARY_UNAVAILABLE;
      }

      if (error.name === "AbortError") {
        return SSEErrorCode.STREAM_ABORTED;
      }

      // Defense-in-depth: upstream layers (SQL client, cache) may wrap an
      // AbortError into ExecutionError, losing `name` but keeping the message.
      if (
        message.includes("operation was aborted") ||
        message.includes("the request was aborted") ||
        message.includes("statement was canceled")
      ) {
        return SSEErrorCode.STREAM_ABORTED;
      }

      // Detect upstream API errors (e.g., from Databricks SDK ApiError)
      if (
        "statusCode" in error &&
        typeof (error as any).statusCode === "number"
      ) {
        return SSEErrorCode.UPSTREAM_ERROR;
      }
    }

    return SSEErrorCode.INTERNAL_ERROR;
  }
}
